// Sample payments shaped like items from Razorpay's GET /v1/payments
// (amounts in paise, times in Unix seconds). To go live, replace this node with
// an HTTP Request to Razorpay that lists payments for the caller; see README.
const PAYMENTS = [
  { id: 'pay_Qd7Lm2Xa9Kp4Tz', order_id: 'order_Qd7Kw1Va5Ls8Pe', amount: 149900, currency: 'INR', status: 'captured', method: 'upi', email: 'asha@customer.example', contact: '+911000000001', created_at: 1793162700, notes: { product: '21-Day Breathwork Reset' }, refund_status: null },
  { id: 'pay_Qd7Kx8Rb3Nw6Hc', order_id: 'order_Qd7Kw1Va5Ls8Pe', amount: 149900, currency: 'INR', status: 'failed', method: 'card', email: 'asha@customer.example', contact: '+911000000001', created_at: 1793162520, notes: { product: '21-Day Breathwork Reset' }, refund_status: null, error_description: 'Payment declined by the bank' },
  { id: 'pay_Qa2Vn6Ty1Gm8Rd', order_id: 'order_Qa2Vm3Ce7Jx2Lb', amount: 79900, currency: 'INR', status: 'refunded', method: 'upi', email: 'ravi@customer.example', contact: '+911000000002', created_at: 1792591800, notes: { product: 'Sleep Better Audio Pack' }, refund_status: 'full' },
  { id: 'pay_Qe4Hs9Wk5Bc2Mn', order_id: 'order_Qe4Hr7Dz3Qy6Fv', amount: 99900, currency: 'INR', status: 'captured', method: 'netbanking', email: 'meera@customer.example', contact: '+911000000003', created_at: 1793327700, notes: { product: 'Desk Yoga Video Course' }, refund_status: null },
];

const ACCESS = { captured: 'active', refunded: 'removed after the refund', failed: 'none, the payment did not complete' };

// One number, many spellings: "+91 10000 00001", "911000000001", "1000000001".
const normalize = (phone) => {
  const digits = String(phone ?? '').replace(/\D/g, '');
  return digits.length === 10 ? `91${digits}` : digits;
};

const caller = normalize($input.first().json.phone);
const purchases = caller.length < 11 ? [] : PAYMENTS
  .filter((payment) => normalize(payment.contact) === caller)
  .map((payment) => ({
    payment_id: payment.id,
    order_id: payment.order_id,
    product: payment.notes.product,
    amount_inr: `₹${(payment.amount / 100).toLocaleString('en-IN')}`,
    status: payment.status,
    method: payment.method,
    date: new Date(payment.created_at * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' }),
    access: ACCESS[payment.status],
    refund_status: payment.refund_status,
    ...(payment.error_description ? { failure_reason: payment.error_description } : {}),
  }));

return [{ json: { found: purchases.length > 0, purchases } }];
